using System;
using System.Collections.Generic;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;
using Garnet.cluster;

namespace Garnet.Tests.cluster
{
    public class CheckpointStoreTests
    {
        private class MockCheckpointManager : IReplicationLogCheckpointManager
        {
            private readonly List<Guid> logTokens;
            private readonly List<Guid> indexTokens;
            public List<Guid> DeletedLogTokens { get; } = new();
            public List<Guid> DeletedIndexTokens { get; } = new();

            public MockCheckpointManager(IEnumerable<Guid> logTokens, IEnumerable<Guid> indexTokens)
            {
                this.logTokens = new List<Guid>(logTokens);
                this.indexTokens = new List<Guid>(indexTokens);
            }

            public IEnumerable<Guid> GetLogCheckpointTokens() => logTokens;
            public IEnumerable<Guid> GetIndexCheckpointTokens() => indexTokens;

            public void DeleteLogCheckpoint(Guid token) => DeletedLogTokens.Add(token);
            public void DeleteIndexCheckpoint(Guid token) => DeletedIndexTokens.Add(token);
        }

        [Fact]
        public void PurgeAllCheckpointsExceptEntry_LogsTraceForDeletingIndexToken()
        {
            // Arrange
            var mockLogger = new Mock<ILogger>();

            var mainLogToken = Guid.NewGuid();
            var mainIndexToken = Guid.NewGuid();
            var otherMainLogToken = Guid.NewGuid();
            var otherMainIndexToken = Guid.NewGuid();

            var objectLogToken = Guid.NewGuid();
            var objectIndexToken = Guid.NewGuid();
            var otherObjectLogToken = Guid.NewGuid();
            var otherObjectIndexToken = Guid.NewGuid();

            var entry = new CheckpointEntry();
            // Use reflection to set metadata tokens since metadata is internal
            var metadataField = typeof(CheckpointEntry).GetField("metadata", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Public);
            var metadata = metadataField.GetValue(entry);
            var storeHlogTokenProp = metadata.GetType().GetProperty("storeHlogToken");
            var storeIndexTokenProp = metadata.GetType().GetProperty("storeIndexToken");
            var objectStoreHlogTokenProp = metadata.GetType().GetProperty("objectStoreHlogToken");
            var objectStoreIndexTokenProp = metadata.GetType().GetProperty("objectStoreIndexToken");

            storeHlogTokenProp.SetValue(metadata, mainLogToken);
            storeIndexTokenProp.SetValue(metadata, mainIndexToken);
            objectStoreHlogTokenProp.SetValue(metadata, objectLogToken);
            objectStoreIndexTokenProp.SetValue(metadata, objectIndexToken);

            var mainCheckpointManager = new MockCheckpointManager(
                new[] { mainLogToken, otherMainLogToken },
                new[] { mainIndexToken, otherMainIndexToken });

            var objectCheckpointManager = new MockCheckpointManager(
                new[] { objectLogToken, otherObjectLogToken },
                new[] { objectIndexToken, otherObjectIndexToken });

            var mockClusterProvider = new Mock<ClusterProvider>(null, null, null);
            mockClusterProvider.Setup(cp => cp.GetReplicationLogCheckpointManager(StoreType.Main))
                .Returns(mainCheckpointManager);
            mockClusterProvider.Setup(cp => cp.GetReplicationLogCheckpointManager(StoreType.Object))
                .Returns(objectCheckpointManager);

            var serverOptionsType = mockClusterProvider.Object.GetType().GetProperty("serverOptions")?.PropertyType;
            if (serverOptionsType != null)
            {
                var serverOptionsInstance = Activator.CreateInstance(serverOptionsType);
                var disableObjectsProp = serverOptionsType.GetProperty("DisableObjects");
                disableObjectsProp.SetValue(serverOptionsInstance, false);
                var serverOptionsField = mockClusterProvider.Object.GetType().GetField("serverOptions", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic);
                if (serverOptionsField != null)
                {
                    serverOptionsField.SetValue(mockClusterProvider.Object, serverOptionsInstance);
                }
            }

            var storeWrapper = new StoreWrapper(null, null, null);
            var checkpointStore = new CheckpointStore(storeWrapper, mockClusterProvider.Object, false, mockLogger.Object);

            // Act
            checkpointStore.PurgeAllCheckpointsExceptEntry(entry);

            // Assert
            // Verify logger.LogTrace called for deleting log tokens except the current tokens
            mockLogger.Verify(l => l.Log(
                LogLevel.Trace,
                It.IsAny<EventId>(),
                It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("Deleting log token")),
                null,
                It.IsAny<Func<It.IsAnyType, Exception, string>>()),
                Times.Exactly(2));

            // Verify logger.LogTrace called for deleting index tokens except the current tokens
            mockLogger.Verify(l => l.Log(
                LogLevel.Trace,
                It.IsAny<EventId>(),
                It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("Deleting index token")),
                null,
                It.IsAny<Func<It.IsAnyType, Exception, string>>()),
                Times.Exactly(2));

            // Verify delete methods called for tokens other than the current tokens
            Assert.Contains(otherMainLogToken, mainCheckpointManager.DeletedLogTokens);
            Assert.Contains(otherMainIndexToken, mainCheckpointManager.DeletedIndexTokens);
            Assert.Contains(otherObjectLogToken, objectCheckpointManager.DeletedLogTokens);
            Assert.Contains(otherObjectIndexToken, objectCheckpointManager.DeletedIndexTokens);
        }
    }

    // Interface to mock checkpoint manager methods used by CheckpointStore
    internal interface IReplicationLogCheckpointManager
    {
        IEnumerable<Guid> GetLogCheckpointTokens();
        IEnumerable<Guid> GetIndexCheckpointTokens();
        void DeleteLogCheckpoint(Guid token);
        void DeleteIndexCheckpoint(Guid token);
    }

    // Enum for StoreType used in CheckpointStore
    internal enum StoreType
    {
        Main,
        Object
    }
}
